package ble

import (
	"bytes"
	"encoding/hex"
	"testing"
)

func golden(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

// Golden chunk layouts generated by the Python reference (ble_framing).
func TestEncodeChunksGolden(t *testing.T) {
	msg := make([]byte, 200)
	for i := range msg {
		msg[i] = byte(i)
	}
	chunks, err := EncodeChunks(msg, 23)
	if err != nil {
		t.Fatal(err)
	}
	wantFirst := golden(t, "fe000c000102030405060708090a0b0c0d0e0f10")
	wantLast := golden(t, "fe0b0cbbbcbdbebfc0c1c2c3c4c5c6c7")
	if len(chunks) != 12 {
		t.Fatalf("mtu23: %d chunks, want 12", len(chunks))
	}
	if !bytes.Equal(chunks[0], wantFirst) {
		t.Errorf("mtu23 chunk0 = %x, want %x", chunks[0], wantFirst)
	}
	if !bytes.Equal(chunks[11], wantLast) {
		t.Errorf("mtu23 chunk11 = %x, want %x", chunks[11], wantLast)
	}

	chunks, err = EncodeChunks(msg, 100)
	if err != nil {
		t.Fatal(err)
	}
	if len(chunks) != 3 {
		t.Fatalf("mtu100: %d chunks, want 3", len(chunks))
	}
	want100 := golden(t, "fe0203bcbdbebfc0c1c2c3c4c5c6c7")
	if !bytes.Equal(chunks[2], want100) {
		t.Errorf("mtu100 chunk2 = %x, want %x", chunks[2], want100)
	}

	single, err := EncodeChunks([]byte("hi"), 23)
	if err != nil {
		t.Fatal(err)
	}
	if len(single) != 1 || !bytes.Equal(single[0], golden(t, "fe00016869")) {
		t.Errorf("single = %x, want [fe00016869]", single)
	}
}

func TestAssemblerRoundTripAndOrder(t *testing.T) {
	msg := bytes.Repeat([]byte("abcdefgh"), 40) // 320 bytes
	chunks, err := EncodeChunks(msg, 23)
	if err != nil {
		t.Fatal(err)
	}
	assembler := NewChunkAssembler()
	for i, chunk := range chunks {
		got, complete := assembler.Feed(chunk)
		if i < len(chunks)-1 {
			if complete {
				t.Fatalf("chunk %d completed early", i)
			}
			continue
		}
		if !complete || !bytes.Equal(got, msg) {
			t.Fatalf("final chunk: complete=%v, equal=%v", complete, bytes.Equal(got, msg))
		}
	}
}

func TestAssemblerUnchunkedAndDisorder(t *testing.T) {
	assembler := NewChunkAssembler()
	// A packet not starting with 0xFE is a complete message.
	if got, complete := assembler.Feed([]byte("error_pairing_invalid_hello")); !complete || string(got) != "error_pairing_invalid_hello" {
		t.Fatalf("unchunked: %q %v", got, complete)
	}
	// Out-of-order chunk discards the buffer.
	message := "0123456789abcdefghijklmnopqrstuvwx" // 34 bytes = 2 chunks at MTU 23
	chunks, _ := EncodeChunks([]byte(message), 23)
	if len(chunks) != 2 {
		t.Fatalf("got %d chunks, want 2", len(chunks))
	}
	if _, complete := assembler.Feed(chunks[1]); complete {
		t.Fatal("chunk 1 first should not complete")
	}
	if _, complete := assembler.Feed(chunks[0]); complete {
		t.Fatal("chunk 0 after discard restarts; should not complete")
	}
	got, complete := assembler.Feed(chunks[1])
	if !complete || string(got) != message {
		t.Fatalf("restart assembly: %q %v", got, complete)
	}
	// total == 0 is discarded.
	if _, complete := assembler.Feed([]byte{0xFE, 0, 0, 1, 2}); complete {
		t.Fatal("total 0 chunk completed a message")
	}
}

func TestEncodeChunksTooMany(t *testing.T) {
	if _, err := EncodeChunks(make([]byte, MaxChunks*17+1), 23); err == nil {
		t.Fatal("expected an error for >255 chunks")
	}
}
